const $=id=>document.getElementById(id), money=n=>'₱'+n.toLocaleString('en-PH');
const categories=[['All','✳'],['Burgers','🍔'],['Pizza','🍕'],['Filipino','🍲'],['Japanese','🍣'],['Healthy','🥗'],['Coffee','☕'],['Desserts','🍰']];
const restaurants=[
{id:0,name:'The Good Burger',type:'Burgers',desc:'Burgers · American · Comfort food',rating:4.9,time:25,fee:39,offer:'20% off your first bite',image:'photo-1568901346375-23c9450c58cd',menu:[['The Classic Smash',249,'Double smashed beef, cheddar, house sauce'],['Crispy Chicken Burger',229,'Golden chicken, slaw, pickles'],['Truffle Fries',119,'Crispy fries, parmesan, truffle mayo']]},
{id:1,name:'Nonna’s Table',type:'Pizza',desc:'Pizza · Italian · Wood-fired',rating:4.8,time:30,fee:0,offer:'Free delivery',image:'photo-1579751626657-72bc17010498',menu:[['Margherita',329,'Tomato, fresh mozzarella, basil'],['Pepperoni',389,'Pepperoni, mozzarella, tomato'],['Creamy Mushroom Pasta',279,'Mushrooms, cream, parmesan']]},
{id:2,name:'Bowl & Bloom',type:'Healthy',desc:'Healthy · Bowls · Feel-good food',rating:4.9,time:20,fee:29,offer:'Fresh picks, happy you',image:'photo-1512621776951-a57141f2eefd',menu:[['Harvest Bowl',249,'Roasted vegetables, quinoa, tahini'],['Chicken Power Bowl',289,'Grilled chicken, brown rice, avocado'],['Green Smoothie',149,'Spinach, mango, banana']]},
{id:3,name:'Kusina ni Lola',type:'Filipino',desc:'Filipino · Home cooking · Rice meals',rating:4.9,time:25,fee:0,offer:'Free delivery',image:'photo-1547592180-85f173990554',menu:[['Chicken Adobo Rice',189,'Slow-braised chicken, garlic rice'],['Sinigang na Baboy',299,'Tamarind broth, pork, seasonal vegetables'],['Lumpiang Shanghai',149,'Crispy pork rolls, sweet chili dip']]},
{id:4,name:'Maki Moments',type:'Japanese',desc:'Japanese · Sushi · Rice bowls',rating:4.7,time:35,fee:49,offer:'A little roll of happiness',image:'photo-1579871494447-9811cf80d66c',menu:[['Salmon Maki',289,'Fresh salmon, rice, nori'],['Chicken Teriyaki Bowl',249,'Teriyaki chicken over steamed rice'],['Gyoza',159,'Five pan-fried dumplings']]},
{id:5,name:'Sunday Coffee Club',type:'Coffee',desc:'Coffee · Desserts · Slow mornings',rating:4.8,time:20,fee:29,offer:'Your daily little ritual',image:'photo-1495474472287-4d71bcdd2085',menu:[['Iced Spanish Latte',159,'Espresso, creamy milk, sweet finish'],['Butter Croissant',119,'Flaky, buttery, baked fresh'],['Chocolate Cake',179,'Rich chocolate, silky ganache']]}];
let category='All',filter='all',sortRating=false,cart=JSON.parse(localStorage.getItem('tendril-cart')||'[]'),order=JSON.parse(localStorage.getItem('tendril-order')||'null'),address=localStorage.getItem('tendril-address')||'Makati, Metro Manila';
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}
function persist(){localStorage.setItem('tendril-cart',JSON.stringify(cart));$('count').textContent=cart.reduce((a,i)=>a+i.qty,0)}
function render(){const q=$('search').value.toLowerCase();let list=restaurants.filter(r=>(category==='All'||r.type===category||(category==='Desserts'&&r.type==='Coffee'))&&(filter==='all'||filter==='top'&&r.rating>=4.9||filter==='fast'&&r.time<30||filter==='free'&&r.fee===0)&&[r.name,r.desc,...r.menu.map(d=>d[0])].join(' ').toLowerCase().includes(q));if(sortRating)list.sort((a,b)=>b.rating-a.rating);$('results').textContent=list.length+' places to love';$('restaurants').innerHTML=list.length?list.map(r=>`<button class="restaurant" data-restaurant="${r.id}"><div class="photo"><img src="https://images.unsplash.com/${r.image}?auto=format&fit=crop&w=750&q=80" alt="${r.desc}"><span class="offer">${r.offer}</span><span class="heart">♡</span></div><h3>${r.name}<span class="rating">★ ${r.rating} <span style="color:#9ba38f">(100+)</span></span></h3><p>${r.desc}</p><div class="meta"><span>◷ ${r.time}–${r.time+10} min</span><span class="${r.fee?'':'free'}">⌁ ${r.fee?money(r.fee)+' delivery':'Free delivery'}</span></div></button>`).join(''):'<div class="empty"><span>⌕</span>No matches yet. Try another craving or filter.</div>';document.querySelectorAll('[data-restaurant]').forEach(b=>b.onclick=()=>openMenu(+b.dataset.restaurant))}
$('categories').innerHTML=categories.map(([n,i])=>`<button class="category ${n==='All'?'selected':''}" data-category="${n}"><span class="icon">${i}</span>${n==='All'?'All cravings':n}</button>`).join('');document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));render()});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});$('search').oninput=render;$('sort').onclick=()=>{sortRating=!sortRating;$('sort').textContent=sortRating?'Highest rated ⌄':'Recommended ⌄';render()};
function openMenu(id){const r=restaurants[id];$('menuContent').innerHTML=`<div class="eyebrow">A LITTLE SOMETHING DELICIOUS</div><h2>${r.name}</h2><p class="muted">★ ${r.rating} · ${r.time}–${r.time+10} min · ${r.fee?money(r.fee)+' delivery':'Free delivery'}</p>${r.menu.map((d,i)=>`<div class="dish"><div><h3>${d[0]}</h3><p>${d[2]}</p><b>${money(d[1])}</b></div><button data-add="${i}" aria-label="Add ${d[0]}">＋</button></div>`).join('')}<p class="muted">Sample menu · one restaurant per order</p>`;document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(cart.length&&cart[0].restaurant!==id){toast('Finish or empty your current bag to switch restaurants.');return}const index=+b.dataset.add,item=cart.find(x=>x.index===index);if(item)item.qty++;else cart.push({restaurant:id,index,qty:1});persist();toast(r.menu[index][0]+' added to your bag')});$('menu').showModal()}
function totals(){const subtotal=cart.reduce((a,i)=>a+restaurants[i.restaurant].menu[i.index][1]*i.qty,0),fee=cart.length?restaurants[cart[0].restaurant].fee:0;return {subtotal,fee,total:subtotal+fee}}
function totalHtml(){const t=totals();return `<div class="totalLine"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="totalLine"><span>Delivery fee</span><span>${t.fee?money(t.fee):'Free'}</span></div><div class="totalLine grand"><span>Total</span><span>${money(t.total)}</span></div>`}
function renderCart(){if(!cart.length){$('cartContent').innerHTML='<div class="empty"><span>♧</span><h3>A little empty, a lot of possibilities.</h3><p>Pick a restaurant and add something delicious.</p></div>';return}$('cartContent').innerHTML=`<p class="muted">From ${restaurants[cart[0].restaurant].name}</p>`+cart.map((x,i)=>`<div class="cartRow"><div><b>${restaurants[x.restaurant].menu[x.index][0]}</b><p>${money(restaurants[x.restaurant].menu[x.index][1]*x.qty)}</p></div><div class="quantity"><button data-change="${i}" data-delta="-1" aria-label="Decrease quantity">−</button>${x.qty}<button data-change="${i}" data-delta="1" aria-label="Increase quantity">＋</button></div></div>`).join('')+totalHtml()+'<button class="primary" id="toCheckout">Continue to checkout →</button>';document.querySelectorAll('[data-change]').forEach(b=>b.onclick=()=>{cart[+b.dataset.change].qty+=+b.dataset.delta;cart=cart.filter(x=>x.qty>0);persist();renderCart()});$('toCheckout').onclick=()=>{$('cart').close();$('deliveryAddress').value=address;$('checkoutTotal').innerHTML=totalHtml();$('checkout').showModal()}}
$('openCart').onclick=()=>{renderCart();$('cart').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('checkoutForm').onsubmit=e=>{e.preventDefault();if(!cart.length)return;const f=new FormData(e.target);order={id:'TD-'+Date.now().toString().slice(-6),name:f.get('name'),address:f.get('address'),restaurant:restaurants[cart[0].restaurant].name,items:cart.map(x=>({name:restaurants[x.restaurant].menu[x.index][0],qty:x.qty})),total:totals().total,created:Date.now(),step:0};localStorage.setItem('tendril-order',JSON.stringify(order));cart=[];persist();$('checkout').close();showTracking()};
function showTracking(){if(!order){$('trackingContent').innerHTML='<h2>Your orders</h2><div class="empty"><span>♧</span>No orders yet. Your next favorite is waiting.</div>'}else{$('trackingContent').innerHTML=`<span class="demoLabel">SIMULATED ORDER · NO REAL DELIVERY</span><h2>${order.step===3?'Enjoy your demo meal!':'Good food is on its way.'}</h2><p class="muted">${order.id} · ${escapeHtml(order.restaurant)}</p><p>For ${escapeHtml(order.name)}<br><small>${escapeHtml(order.address)}</small></p>${['Order confirmed','Kitchen is preparing','Rider is on the way','Delivered'].map((s,i)=>`<div class="trackStep ${i<=order.step?'done':''}">${i<=order.step?'✓':'○'} ${s}<small>${['Your demo order has been received','Freshly made with a little love','Heading to your doorstep','Your sample order is complete'][i]}</small></div>`).join('')}<p class="muted">${order.items.map(i=>i.qty+' × '+escapeHtml(i.name)).join('<br>')}</p><div class="totalLine grand"><span>Total · Cash on delivery</span><span>${money(order.total)}</span></div>${order.step<3?'<button class="primary" id="advance">Simulate next delivery step →</button>':'<button class="primary" id="again">Find another favorite →</button>'}`;if($('advance'))$('advance').onclick=()=>{order.step++;localStorage.setItem('tendril-order',JSON.stringify(order));showTracking()};if($('again'))$('again').onclick=()=>$('tracking').close()}if(!$('tracking').open)$('tracking').showModal()}
$('orders').onclick=showTracking;$('discover').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('location').onclick=()=>{$('addressInput').value=address;$('addressDialog').showModal()};$('addressForm').onsubmit=e=>{e.preventDefault();address=$('addressInput').value.trim();localStorage.setItem('tendril-address',address);$('addressLabel').textContent=address;$('addressDialog').close();toast('Delivery address updated')};$('addressLabel').textContent=address;persist();render();
// Expose order history on compact screens without taking header space.
const mobileOrders=document.createElement('button');mobileOrders.textContent='My orders ↗';mobileOrders.onclick=showTracking;document.querySelector('footer').append(mobileOrders);
